#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 5500;
const int MAX_M = 35500;
const int INF = 0x3B9ACA00;

struct Edge { int next, target, capacity, cost; };
vector<Edge> edgeList(MAX_M+5);
vector<int> adjacencyList(MAX_N+5);
int edgeCounter = 1;

void insertEdge(int source, int dest, int cap, int cost) {
    edgeList[++edgeCounter] = {adjacencyList[source], dest, cap, cost};
    adjacencyList[source] = edgeCounter;
    edgeList[++edgeCounter] = {adjacencyList[dest], source, 0, -cost};
    adjacencyList[dest] = edgeCounter;
}

int src, dst, prevNode[MAX_N], edgeUsed[MAX_N], minFlow[MAX_N], distNode[MAX_N];
bool inBfs[MAX_N];
queue<int> bfsQueue;

int spfa() {
    fill(distNode+1, distNode+dst+1, INF);
    fill(minFlow+1, minFlow+dst+1, 0);
    minFlow[src] = INF;
    distNode[src] = 0;
    bfsQueue.push(src);
    inBfs[src] = true;

    while (!bfsQueue.empty()) {
        int cur = bfsQueue.front();
        inBfs[cur] = false;
        bfsQueue.pop();

        for (int idx = adjacencyList[cur]; idx; idx = edgeList[idx].next) {
            if (edgeList[idx].capacity && distNode[edgeList[idx].target] > distNode[cur] + edgeList[idx].cost) {
                distNode[edgeList[idx].target] = distNode[cur] + edgeList[idx].cost;
                minFlow[edgeList[idx].target] = min(minFlow[cur], edgeList[idx].capacity);
                edgeUsed[edgeList[idx].target] = idx;
                prevNode[edgeList[idx].target] = cur;
                if (!inBfs[edgeList[idx].target]) {
                    inBfs[edgeList[idx].target] = true;
                    bfsQueue.push(edgeList[idx].target);
                }
            }
        }
    }
    return minFlow[dst];
}

int N, M, K, COST_BASE, COST_DIST, plan[105][105], state[105][105];
struct Path { int start, end; } paths[105];

#define NODE_ID(r,c) ((r)*N+(c))

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> M >> K >> COST_BASE >> COST_DIST;

    src = NODE_ID(N+K, N) + 1;
    dst = src + 2;

    insertEdge(NODE_ID(0,1), dst, INF, 0);

    for (int i=1, tmp; i<=K; ++i) {
        cin >> tmp;
        insertEdge(src, NODE_ID(0,tmp), 1, 0);
    }

    for (int i=1; i<=M; ++i) {
        cin >> paths[i*2].start >> paths[i*2].end;
        paths[i*2-1] = {paths[i*2].end, paths[i*2].start};
    }
    M *= 2;

    for (int day=1; day<=N+K; ++day) {
        for (int j=1; j<=N; ++j)
            insertEdge(NODE_ID(day-1,j), NODE_ID(day,j), INF, 0);
        for (int j=1; j<=M; ++j) {
            insertEdge(NODE_ID(day-1, paths[j].start), NODE_ID(day, paths[j].end), 1, COST_DIST);
            plan[day][j] = edgeCounter;
            state[day][j] = 1;
        }
        insertEdge(NODE_ID(day,1), dst, INF, day*COST_BASE);
    }

    int augmentVal, ans=0;
    while (augmentVal = spfa()) {
        int node = dst;
        while (node != src) {
            int prev = prevNode[node];
            edgeList[edgeUsed[node]].capacity -= augmentVal;
            edgeList[edgeUsed[node]^1].capacity += augmentVal;
            node = prev;
        }
        ans += distNode[dst] * augmentVal;

        for (int day=1; day<=N+N; ++day)
            for (int j=1; j<=M; ++j)
                if (edgeList[plan[day][j]].capacity) {
                    state[day][j]++;
                    insertEdge(NODE_ID(day-1, paths[j].start), NODE_ID(day, paths[j].end), 1, COST_DIST*(state[day][j]*2-1));
                    plan[day][j] = edgeCounter;
                }
    }

    cout << ans << '\n';
    return 0;
}
